<div class="toolbar"><form class="filters"><input type="date" name="date" value="<?= e($date) ?>" aria-label="Fecha de la agenda"><select name="mode" aria-label="Vista"><?php foreach(['day'=>'Día','week'=>'Semana','month'=>'Mes'] as $v=>$n): ?><option value="<?= $v ?>"<?= selected($mode,$v) ?>><?= $n ?></option><?php endforeach; ?></select><select name="dentist" aria-label="Filtrar profesional"><option value="">Todos los profesionales</option><?php foreach($dentists as $d): ?><option value="<?= (int)$d['id'] ?>"<?= selected($_GET['dentist'] ?? '',$d['id']) ?>><?= e($d['name']) ?></option><?php endforeach; ?></select><select name="status" aria-label="Filtrar estado"><option value="">Todos los estados</option><?php foreach(['pending','confirmed','attended','completed','cancelled','no_show'] as $s): ?><option value="<?= $s ?>"<?= selected($_GET['status'] ?? '',$s) ?>><?= e(label($s)) ?></option><?php endforeach; ?></select><button class="button secondary">Aplicar</button></form><a class="button" href="<?= e(\App\Services\WorkspaceContext::url('/admin/appointments',['new'=>1],['edit','view'])) ?>"><?= icon('plus',18) ?> Nueva cita</a></div>
<?php if(isset($_GET['new']) || $edit || ($error && $_SERVER['REQUEST_METHOD']==='POST')): $a=$error ? $_POST:($edit ?? []); $dt=isset($a['starts_at']) ? local_date($a['starts_at'],'Y-m-d'):($a['date'] ?? date('Y-m-d')); $tm=isset($a['starts_at']) ? local_date($a['starts_at'],'H:i'):($a['time'] ?? '09:00'); ?><section class="panel form-panel"><h2><?= $edit ? 'Confirmar o reprogramar cita':'Crear cita' ?></h2><?php if(!empty($a['contact_name'])): ?><p class="notice">Solicitud de <?= e($a['contact_name']) ?> · <?= e($a['contact_phone']) ?> · <?= e($a['contact_email']) ?>. Selecciona o registra al paciente para confirmarla.</p><?php endif; ?><form method="post" class="form-grid" data-loading><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($a['id'] ?? 0) ?>"><?php choose('patient_id','Paciente',patient_options($patients),$a['patient_id'] ?? ''); choose('dentist_id','Profesional',array_column(array_filter($dentists,fn($d)=>$d['active']),'name','id'),$a['dentist_id'] ?? ''); choose('service_id','Servicio',array_column($services,'name','id'),$a['service_id'] ?? ''); choose('status','Estado',array_combine(['pending','confirmed','attended','completed','cancelled','no_show'],array_map('label',['pending','confirmed','attended','completed','cancelled','no_show'])),$a['status'] ?? 'confirmed'); field('date','Fecha',$dt,'date'); field('time','Hora local',$tm,'time'); area('reason','Motivo de consulta',$a['reason'] ?? ''); ?><div class="full actions"><button class="button">Guardar cita</button><a class="button secondary" href="<?= e(\App\Services\WorkspaceContext::url('/admin/appointments',[],['new','edit'])) ?>">Volver</a></div></form></section><?php endif; ?>
<section class="panel"><div class="panel-heading"><h2><?= $from->format('d/m/Y') ?> — <?= $to->modify('-1 day')->format('d/m/Y') ?></h2><span class="muted"><?= count($rows) ?> citas · Hora local</span></div><div class="calendar-grid <?= e($mode) ?>"><?php $byDay=[]; foreach($rows as $a) $byDay[local_date($a['starts_at'],'Y-m-d')][]=$a; for($day=$from;$day<$to;$day=$day->modify('+1 day')): ?><div class="calendar-day <?= $day->format('Y-m-d')===date('Y-m-d') ? 'today':'' ?>"><div class="day-label"><span><?= ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][(int)$day->format('w')] ?></span><strong><?= $day->format('d') ?></strong></div><?php foreach($byDay[$day->format('Y-m-d')] ?? [] as $a): ?><a class="calendar-event <?= e($a['status']) ?>" href="<?= e(\App\Services\WorkspaceContext::url('/admin/appointments',['edit'=>$a['id']],['new','view'])) ?>"><strong><?= local_date($a['starts_at'],'H:i') ?> · <?= e($a['patient']) ?></strong><small><?= e($a['service']) ?></small><small><?= e($a['dentist'] ?: 'Profesional por asignar') ?></small><span><?= e(label($a['status'])) ?></span></a><?php endforeach; ?></div><?php endfor; ?></div></section>
<?php if($requests): ?><section class="panel"><div class="panel-heading"><h2>Solicitudes del sitio web</h2><span class="muted">Pendientes de revisión</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Solicitante</th><th>Contacto</th><th>Servicio</th><th>Horario solicitado</th><th>Acción</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?= e($r['contact_name']) ?></td><td><?= e($r['contact_phone']) ?><small><?= e($r['contact_email']) ?></small></td><td><?= e($r['service']) ?></td><td><?= local_date($r['starts_at']) ?></td><td><a class="table-link" href="<?= e(\App\Services\WorkspaceContext::url('/admin/appointments',['edit'=>$r['id']],['new','view'])) ?>">Revisar solicitud</a><form method="post" data-confirm="Se cancelar? esta solicitud sin asignar una cita."><?= csrf_field() ?><input type="hidden" name="action" value="reject_request"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="button small secondary">Cancelar solicitud</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<details class="panel"><summary>Disponibilidad de los profesionales</summary><div class="availability-grid"><?php foreach($dentists as $d): ?><div><strong><?= e($d['name']) ?></strong><p><?= $d['active'] ? 'Lunes a sábado · '.e(substr($d['work_start'],0,5)).' a '.e(substr($d['work_end'],0,5)):'Inactivo' ?></p><small>Las citas de la agenda ocupan los intervalos mostrados. La disponibilidad final se comprueba al guardar.</small></div><?php endforeach; ?></div></details>
